analytics:Object.freeze({evidence:['ads','finance','inventory'],essential:['ads'],kpis:[['Ads rows','ads'],['Unified rows','finance'],['Inventory rows','inventory']],tasks:[['ads','import','Load Amazon Ads evidence'],['finance','import','Load Unified evidence'],['inventory','inventory-risk','Load inventory evidence'],['','anomaly-center','Review Anomaly Center']]})
